-- Drive Learn - atualização auditada do catálogo de ônibus Volvo.
-- Gerado em 2026-09-16; idempotente; preenche lacunas sem substituir dados válidos já cadastrados.
-- Não confundir peso/tara do chassi com PBT. Protótipos e lançamentos futuros ficam inativos.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS schema_migrations (versao VARCHAR(80) NOT NULL PRIMARY KEY, descricao VARCHAR(255) NOT NULL, aplicado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modelo_especificacoes_tecnicas (modelo_id BIGINT UNSIGNED NOT NULL,chave VARCHAR(80) NOT NULL,rotulo VARCHAR(120) NOT NULL,valor VARCHAR(255) NOT NULL,unidade VARCHAR(30) NULL,fonte_url VARCHAR(700) NULL,conferido_em DATE NULL,PRIMARY KEY(modelo_id,chave),INDEX idx_met_chave_028(chave),CONSTRAINT fk_met_modelo_028 FOREIGN KEY(modelo_id) REFERENCES modelos(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



-- Volvo B380R 4x2
UPDATE modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id SET m.motor=CASE WHEN m.motor IS NULL OR TRIM(m.motor)='' OR LOWER(TRIM(m.motor)) IN ('não informado','nao informado','n/d') THEN 'Volvo D13K380, 12,8 l, 6 cilindros em linha, Euro 6' ELSE m.motor END,m.potencia=CASE WHEN m.potencia IS NULL OR TRIM(m.potencia)='' OR LOWER(TRIM(m.potencia)) IN ('não informado','nao informado','n/d') THEN '380 hp (279 kW) @ 1.700 rpm' ELSE m.potencia END,m.torque=CASE WHEN m.torque IS NULL OR TRIM(m.torque)='' OR LOWER(TRIM(m.torque)) IN ('não informado','nao informado','n/d') THEN '1.814 Nm @ 830-1.400 rpm' ELSE m.torque END,m.transmissao=CASE WHEN m.transmissao IS NULL OR TRIM(m.transmissao)='' OR LOWER(TRIM(m.transmissao)) IN ('não informado','nao informado','n/d') THEN 'Volvo I-Shift automatizada' ELSE m.transmissao END,m.pbt=CASE WHEN m.pbt IS NULL OR TRIM(m.pbt)='' OR LOWER(TRIM(m.pbt)) IN ('não informado','nao informado','n/d') THEN '19.500 kg' ELSE m.pbt END,m.relacao_reducao=CASE WHEN m.relacao_reducao IS NULL OR TRIM(m.relacao_reducao)='' OR LOWER(TRIM(m.relacao_reducao)) IN ('não informado','nao informado','n/d') THEN '2,64:1 (2,85:1 opcional)' ELSE m.relacao_reducao END,m.descricao=CASE WHEN m.descricao IS NULL OR TRIM(m.descricao)='' OR LOWER(TRIM(m.descricao)) IN ('não informado','nao informado','n/d') THEN 'Especificações atualizadas a partir de fonte oficial pública.' ELSE m.descricao END,m.especificacoes=JSON_MERGE_PATCH('{"tipo_veiculo":"Ônibus","energia":"Diesel/HVO","configuracao":"4x2","entre_eixos":"4.000","comprimento_chassi":"9.400 / 9.750","emissoes":"Euro 6 / Proconve P8","mercado":"Rodoviário e fretamento","fonte_oficial":"https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-data-sheet-b380r-4x2-euro-6-pt-br-2022.pdf"}',COALESCE(m.especificacoes,JSON_OBJECT())) WHERE ma.slug='volvo' AND (m.slug='volvo-b380r-4x2-onibus' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Volvo B380R 4x2')));

