INSERT INTO marcas(nome,slug,pais_origem,site_oficial,descricao,ativo) VALUES ('Volvo','volvo','Suécia','https://www.volvobuses.com/br/','Fabricante de chassis e veículos para transporte de passageiros.',1) ON DUPLICATE KEY UPDATE site_oficial=VALUES(site_oficial),descricao=COALESCE(NULLIF(descricao,''),VALUES(descricao));
