INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo B380R 4x2','volvo-b380r-4x2-onibus','Especificações atualizadas a partir de fonte oficial pública.','Volvo D13K380, 12,8 l, 6 cilindros em linha, Euro 6','380 hp (279 kW) @ 1.700 rpm','1.814 Nm @ 830-1.400 rpm','Volvo I-Shift automatizada','19.500 kg',NULL,'2,64:1 (2,85:1 opcional)','{"tipo_veiculo":"Ônibus","energia":"Diesel/HVO","configuracao":"4x2","entre_eixos":"4.000","comprimento_chassi":"9.400 / 9.750","emissoes":"Euro 6 / Proconve P8","mercado":"Rodoviário e fretamento","fonte_oficial":"https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-data-sheet-b380r-4x2-euro-6-pt-br-2022.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='B13R Rodoviários' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-b380r-4x2-onibus' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo B380R 4x2')))) LIMIT 1;
INSERT INTO modelo_especificacoes_tecnicas(modelo_id,chave,rotulo,valor,unidade,fonte_url,conferido_em) SELECT m.id,'pbt','PBT','19.500 kg',NULL,'https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html','2026-09-16' FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND (m.slug='volvo-b380r-4x2-onibus' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Volvo B380R 4x2')) ) LIMIT 1 ON DUPLICATE KEY UPDATE rotulo=VALUES(rotulo),valor=CASE WHEN valor IS NULL OR TRIM(valor)='' OR LOWER(TRIM(valor)) IN ('não informado','nao informado','n/d') THEN VALUES(valor) ELSE valor END,fonte_url=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(fonte_url) ELSE fonte_url END,conferido_em=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(conferido_em) ELSE conferido_em END;
INSERT INTO modelo_especificacoes_tecnicas(modelo_id,chave,rotulo,valor,unidade,fonte_url,conferido_em) SELECT m.id,'relacao_reducao','Relação de redução','2,64:1 (2,85:1 opcional)',NULL,'https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html','2026-09-16' FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND (m.slug='volvo-b380r-4x2-onibus' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Volvo B380R 4x2')) ) LIMIT 1 ON DUPLICATE KEY UPDATE rotulo=VALUES(rotulo),valor=CASE WHEN valor IS NULL OR TRIM(valor)='' OR LOWER(TRIM(valor)) IN ('não informado','nao informado','n/d') THEN VALUES(valor) ELSE valor END,fonte_url=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(fonte_url) ELSE fonte_url END,conferido_em=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(conferido_em) ELSE conferido_em END;
