INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo B460R 6x2','volvo-b460r-6x2-onibus','Especificações atualizadas a partir de fonte oficial pública.','Volvo D13K460, 12,8 l, 6 cilindros em linha, Euro 6','460 hp (345 kW) @ 1.400-1.800 rpm','2.300 Nm @ 900-1.400 rpm','Volvo I-Shift automatizada','24.750 / 26.500 kg',NULL,'2,64:1 (2,85:1 opcional)','{"tipo_veiculo":"Ônibus","energia":"Diesel/HVO","configuracao":"6x2","entre_eixos":"4.000 + 1.400","comprimento_chassi":"10.220 / 10.570","emissoes":"Euro 6 / Proconve P8","mercado":"Rodoviário e fretamento","fonte_oficial":"https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-data-sheet-b460r-6x2-euro-6-pt-br-2022.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='B13R Rodoviários' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-b460r-6x2-onibus' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo B460R 6x2')))) LIMIT 1;
