INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo B510R 8x2','volvo-b510r-8x2-onibus','Especificações atualizadas a partir de fonte oficial pública.','Volvo D13K500, 12,8 l, 6 cilindros em linha, Euro 6','500 hp (368 kW) @ 1.530-1.800 rpm','2.500 Nm @ 980-1.270 rpm','Volvo I-Shift automatizada','29.250 kg',NULL,'2,64:1 (2,85:1 opcional)','{"tipo_veiculo":"Ônibus","energia":"Diesel/HVO","configuracao":"8x2","entre_eixos":"2.600 + 1.400 + 1.400","comprimento_chassi":"10.470","emissoes":"Euro 6 / Proconve P8","mercado":"Rodoviário e fretamento","fonte_oficial":"https://www.volvobuses.com/br/fretamento-e-rodoviario/volvo-b13r/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-data-sheet-b510r-8x2-euro-6-pt-br-2022.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='B13R Rodoviários' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-b510r-8x2-onibus' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo B510R 8x2')))) LIMIT 1;
