INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo B320R LE 4x2','volvo-b320r-le-4x2','Especificações atualizadas a partir de fonte oficial pública.','Volvo D8K, 7,7 l, 6 cilindros em linha, Euro 6','320 hp (240 kW)','1.224 Nm @ 1.050-1.600 rpm','ZF 6AP1420B, 6 marchas, ou Voith D864.6, 4 marchas','19.500 kg',NULL,'5,63:1','{"tipo_veiculo":"Ônibus","energia":"Diesel","configuracao":"4x2, entrada baixa","entre_eixos":"3.500","emissoes":"Euro 6 / Proconve P8","mercado":"Urbano","fonte_oficial":"https://www.volvobuses.com/br/Rodoviario/volvo-b320r-le/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-b320rle-4x2.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='B320R Urbanos' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-b320r-le-4x2' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo B320R LE 4x2')))) LIMIT 1;
