INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo BZR Elétrico 4x2 Piso Médio','volvo-bzr-eletrico-4x2-piso-medio','Especificações atualizadas a partir de fonte oficial pública.','Volvo EPT 402 ou EPT 802','200 kW ou 400 kW (pico)','425 Nm ou 850 Nm no motor','Automatizada de 2 velocidades','20.800 kg',NULL,NULL,'{"tipo_veiculo":"Ônibus","energia":"100% elétrico","configuracao":"4x2, piso médio","entre_eixos":"4.000 (transporte)","comprimento_carroceria":"9.500-13.200","bateria":"Até 540 kWh na oferta atual","carregamento":"CCS2 até 250 kW / OppCharge até 450 kW","mercado":"Urbano","fonte_oficial":"https://www.volvobuses.com/br/Rodoviario/volvo-bzr-electric/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-volvo-bzr-electric-4x2-medium-floor-data-sheet.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='BZR Elétrico' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-bzr-eletrico-4x2-piso-medio' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo BZR Elétrico 4x2 Piso Médio')))) LIMIT 1;
