INSERT INTO modelo_documentos(modelo_id,tipo,titulo,arquivo,url_origem,fonte_pagina,ativo) SELECT m.id,'ficha_tecnica','Documento técnico oficial - Volvo BZRT Elétrico Articulado','/public/assets/documents/modelos/volvo-20260915-volvo-bzrt-eletrico-articulado.pdf','https://www.volvobuses.com/br/Rodoviario/volvo-bzrt-electric/specifications.html','https://www.volvobuses.com/br/Rodoviario/volvo-bzrt-electric/specifications.html',1 FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND (m.slug='volvo-bzrt-eletrico-articulado' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Volvo BZRT Elétrico Articulado'))) LIMIT 1 ON DUPLICATE KEY UPDATE titulo=COALESCE(NULLIF(titulo,''),VALUES(titulo)),arquivo=COALESCE(NULLIF(arquivo,''),VALUES(arquivo)),url_origem=COALESCE(NULLIF(url_origem,''),VALUES(url_origem)),fonte_pagina=COALESCE(NULLIF(fonte_pagina,''),VALUES(fonte_pagina));
