INSERT INTO modelo_documentos(modelo_id,tipo,titulo,arquivo,url_origem,fonte_pagina,ativo) SELECT m.id,'ficha_tecnica','Documento técnico oficial - Volvo BZRT Elétrico Biarticulado','/public/assets/documents/modelos/volvo-20260915-volvo-bzrt-iartic.pdf','https://www.volvobuses.com/br/Rodoviario/volvo-bzrt-electric/specifications.html','https://www.volvobuses.com/br/Rodoviario/volvo-bzrt-electric/specifications.html',1 FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND (m.slug='volvo-bzrt-eletrico-biarticulado' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Volvo BZRT Elétrico Biarticulado'))) LIMIT 1 ON DUPLICATE KEY UPDATE titulo=COALESCE(NULLIF(titulo,''),VALUES(titulo)),arquivo=COALESCE(NULLIF(arquivo,''),VALUES(arquivo)),url_origem=COALESCE(NULLIF(url_origem,''),VALUES(url_origem)),fonte_pagina=COALESCE(NULLIF(fonte_pagina,''),VALUES(fonte_pagina));
INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Volvo BZL Elétrico 4x2','volvo-bzl-eletrico-4x2','Especificações atualizadas a partir de fonte oficial pública.','Volvo EPT 402 ou EPT 802','200 kW ou 400 kW (pico)','425 Nm ou 850 Nm no motor','Automatizada de 2 velocidades','19.500 kg',NULL,NULL,'{"tipo_veiculo":"Ônibus","energia":"100% elétrico","configuracao":"4x2, entrada baixa","comprimento_chassi":"8.515","comprimento_carroceria":"9.500-13.000","bateria":"NCA 282/376/470 kWh ou LFP 350/500 kWh","carregamento":"CCS2 até 250 kW; OppCharge conforme bateria","mercado":"Urbano","fonte_oficial":"https://www.volvobuses.com/br/Rodoviario/volvo-bzl-electric/specifications.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/volvo-20260915-data-sheet-bzl-electric-en-2021.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volvo' AND f.nome='BZL Elétrico' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volvo' AND (mx.slug='volvo-bzl-eletrico-4x2' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Volvo BZL Elétrico 4x2')))) LIMIT 1;
